(function(){var f=document.createElement('div');f.style.position='absolute';f.style.visibility='hidden';f.style.display='flex';f.style.flexDirection='column';f.style.rowGap='1px';
f.appendChild(document.createElement('div'));f.appendChild(document.createElement('div'));document.body.appendChild(f);var ok=f.scrollHeight===1;f.parentNode.removeChild(f);
if(ok)document.documentElement.classList.add('fg')})();

const GUA=[{"no":1,"full":"乾为天","name":"乾","kw":"自强","ci":"乾：元亨利贞。","ciB":"大有可为，守住正道就会顺。","xiang":"天行健，君子以自强不息。","xiangB":"像天一样不停歇，一点点变强。","up":"乾","lo":"乾","yao":[["初九","潜龙勿用。","还在积蓄的时候，先别急着出手。"],["九二","见龙在田，利见大人。","开始被看见了，去见能帮你的人。"],["九三","君子终日乾乾，夕惕若；厉，无咎。","白天努力，晚上反省，就不会出错。"],["九四","或跃在渊，无咎。","可以试着一跃，退回来也没关系。"],["九五","飞龙在天，利见大人。","正当其时，放手去做，也去找同伴。"],["上九","亢龙有悔。","到顶了要知道收，太满会后悔。"]]},{"no":2,"full":"坤为地","name":"坤","kw":"承载","ci":"坤：元亨，利牝马之贞。君子有攸往，先迷后得主。利西南得朋，东北丧朋。安贞吉。","ciB":"柔顺地跟随，先迷后得，安守就好。","xiang":"地势坤，君子以厚德载物。","xiangB":"像大地一样厚实，能容得下事。","up":"坤","lo":"坤","yao":[["初六","履霜，坚冰至。","踩到薄霜，就该留意寒冬要来。"],["六二","直方大，不习，无不利。","正直、方正、宽厚，不刻意也顺。"],["六三","含章可贞。或从王事，无成有终。","有才华先藏着，做事不求功名。"],["六四","括囊，无咎无誉。","扎紧口袋少说话，平安就好。"],["六五","黄裳，元吉。","谦和低调，反而大吉。"],["上六","龙战于野，其血玄黄。","硬碰硬会两败俱伤，该停手了。"]]},{"no":3,"full":"水雷屯","name":"屯","kw":"初生","ci":"屯：元亨利贞。勿用有攸往，利建侯。","ciB":"万事开头难，先打好基础别冒进。","xiang":"云雷屯，君子以经纶。","xiangB":"乱糟糟的时候，正好理出头绪。","up":"坎","lo":"震","yao":[["初九","盘桓，利居贞，利建侯。","犹豫徘徊没关系，先站稳脚跟。"],["六二","屯如邅如，乘马班如。匪寇婚媾，女子贞不字，十年乃字。","进展慢、绕弯路，不急着答应。"],["六三","即鹿无虞，唯入于林中。君子几，不如舍。往吝。","没有向导别贸然深入，舍得放下。"],["六四","乘马班如，求婚媾，往吉，无不利。","主动去找合适的伙伴，会顺利。"],["九五","屯其膏，小贞吉，大贞凶。","资源有限，小事可成，大事缓缓。"],["上六","乘马班如，泣血涟如。","进退两难很难受，这一阵会过去。"]]},{"no":4,"full":"山水蒙","name":"蒙","kw":"启蒙","ci":"蒙：亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎则不告。利贞。","ciB":"诚心问一次就好，反复问反而不清楚。","xiang":"山下出泉，蒙。君子以果行育德。","xiangB":"像山泉一样，果断前行，慢慢养德。","up":"艮","lo":"坎","yao":[["初六","发蒙，利用刑人，用说桎梏。以往，吝。","立点规矩来开窍，但别太严苛。"],["九二","包蒙，吉。纳妇吉。子克家。","包容不懂的人，你能撑起这个家。"],["六三","勿用取女，见金夫，不有躬。无攸利。","别被眼前的好处迷了心。"],["六四","困蒙，吝。","困在不懂里会吃亏，去问去学。"],["六五","童蒙，吉。","像孩子一样虚心，就是好事。"],["上九","击蒙。不利为寇，利御寇。","纠正错误是为了防护，不是攻击。"]]},{"no":5,"full":"水天需","name":"需","kw":"等待","ci":"需：有孚，光亨，贞吉。利涉大川。","ciB":"心里有底，耐心等，时机会来。","xiang":"云上于天，需。君子以饮食宴乐。","xiangB":"雨还没下，先好好吃饭休息。","up":"坎","lo":"乾","yao":[["初九","需于郊，利用恒，无咎。","在远处等着，保持平常心。"],["九二","需于沙，小有言，终吉。","有些闲话不用理，最后是好的。"],["九三","需于泥，致寇至。","陷在泥里等，容易招来麻烦。"],["六四","需于血，出自穴。","处境危险，先从坑里出来。"],["九五","需于酒食，贞吉。","边等边吃好喝好，守正就吉。"],["上六","入于穴，有不速之客三人来，敬之终吉。","有意外的人来，客气对待会帮到你。"]]},{"no":6,"full":"天水讼","name":"讼","kw":"争执","ci":"讼：有孚，窒惕，中吉，终凶。利见大人，不利涉大川。","ciB":"有理也要适可而止，争到底不好。","xiang":"天与水违行，讼。君子以作事谋始。","xiangB":"做事前想清楚，免得日后起争执。","up":"乾","lo":"坎","yao":[["初六","不永所事，小有言，终吉。","争执别拖长，说几句就算了。"],["九二","不克讼，归而逋，其邑人三百户无眚。","争不赢就退回来，反而安全。"],["六三","食旧德，贞厉，终吉。或从王事，无成。","守着本分过日子，最后是好的。"],["九四","不克讼，复即命，渝安贞，吉。","放下争执，回到正轨，就安稳了。"],["九五","讼，元吉。","有公正的人主持，事情会解决。"],["上九","或锡之鞶带，终朝三褫之。","争来的东西，也很快会失去。"]]},{"no":7,"full":"地水师","name":"师","kw":"带队","ci":"师：贞，丈人吉，无咎。","ciB":"带人做事，要有经验的人领头。","xiang":"地中有水，师。君子以容民畜众。","xiangB":"像地里蓄水，包容大家才聚得起人。","up":"坤","lo":"坎","yao":[["初六","师出以律，否臧，凶。","一开始就要有规矩，乱了会出错。"],["九二","在师中，吉无咎，王三锡命。","身处中心被信任，做得好。"],["六三","师或舆尸，凶。","别让不合适的人做主，会失败。"],["六四","师左次，无咎。","暂时退一步，没有错。"],["六五","田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。","有理可讲，但要用对的人。"],["上六","大君有命，开国承家，小人勿用。","论功分配时，别重用小人。"]]},{"no":8,"full":"水地比","name":"比","kw":"亲近","ci":"比：吉。原筮，元永贞，无咎。不宁方来，后夫凶。","ciB":"找到可以依靠的人，别来太迟。","xiang":"地上有水，比。先王以建万国，亲诸侯。","xiangB":"像水贴着大地，和人亲近相连。","up":"坎","lo":"坤","yao":[["初六","有孚，比之，无咎。有孚盈缶，终来有它吉。","真心待人，会有意外的好事。"],["六二","比之自内，贞吉。","从内心去亲近，守正就好。"],["六三","比之匪人。","亲近错了人，要小心。"],["六四","外比之，贞吉。","向外结交贤人，是好事。"],["九五","显比，王用三驱，失前禽。邑人不诫，吉。","坦荡待人，来去自由，不强留。"],["上六","比之无首，凶。","一直不肯靠近谁，会落单。"]]},{"no":9,"full":"风天小畜","name":"小畜","kw":"小积","ci":"小畜：亨。密云不雨，自我西郊。","ciB":"云很厚还没下雨，再积累一点。","xiang":"风行天上，小畜。君子以懿文德。","xiangB":"先修好自己的内在和涵养。","up":"巽","lo":"乾","yao":[["初九","复自道，何其咎？吉。","回到自己的路上，没有错。"],["九二","牵复，吉。","被拉回正轨，也是好事。"],["九三","舆说辐，夫妻反目。","车轮脱了，关系容易闹僵。"],["六四","有孚，血去惕出，无咎。","真诚待人，担忧会散去。"],["九五","有孚挛如，富以其邻。","真诚相连，和身边人一起变好。"],["上九","既雨既处，尚德载。妇贞厉。月几望，君子征凶。","雨下了就停下，别再贪进。"]]},{"no":10,"full":"天泽履","name":"履","kw":"谨行","ci":"履：履虎尾，不咥人，亨。","ciB":"小心翼翼走过险处，也能平安。","xiang":"上天下泽，履。君子以辨上下，定民志。","xiangB":"分清位置和分寸，心就安定。","up":"乾","lo":"兑","yao":[["初九","素履，往无咎。","朴素地走自己的路就好。"],["九二","履道坦坦，幽人贞吉。","路很平坦，安静的人走得稳。"],["六三","眇能视，跛能履。履虎尾，咥人，凶。武人为于大君。","高估自己去冒险，会受伤。"],["九四","履虎尾，愬愬，终吉。","战战兢兢，最后平安。"],["九五","夬履，贞厉。","太果断强硬，要留意危险。"],["上九","视履考祥，其旋元吉。","回头看看走过的路，会很圆满。"]]},{"no":11,"full":"地天泰","name":"泰","kw":"通达","ci":"泰：小往大来，吉亨。","ciB":"付出小，收获大，上下都通了。","xiang":"天地交，泰。后以财成天地之道，辅相天地之宜，以左右民。","xiangB":"顺着天时，把好时光安排好。","up":"坤","lo":"乾","yao":[["初九","拔茅，茹以其汇，征吉。","拔起一根草带起一片，结伴去做。"],["九二","包荒，用冯河，不遐遗，朋亡，得尚于中行。","包容一点，不结小圈子，走中道。"],["九三","无平不陂，无往不复。艰贞无咎。勿恤其孚，于食有福。","有平就有坡，别担心，有福可享。"],["六四","翩翩不富以其邻，不戒以孚。","放下身段，和邻里真诚往来。"],["六五","帝乙归妹，以祉元吉。","低姿态的结合，带来福气。"],["上六","城复于隍，勿用师。自邑告命，贞吝。","好景要转了，别硬撑，先守住。"]]},{"no":12,"full":"天地否","name":"否","kw":"闭塞","ci":"否：否之匪人。不利君子贞。大往小来。","ciB":"上下不通的时候，付出多回报少。","xiang":"天地不交，否。君子以俭德辟难，不可荣以禄。","xiangB":"低调节制，躲开麻烦，不贪名利。","up":"乾","lo":"坤","yao":[["初六","拔茅，茹以其汇，贞吉，亨。","和同伴一起守着，也会通。"],["六二","包承，小人吉；大人否，亨。","别为顺从而顺从，守住自己。"],["六三","包羞。","心里有愧的事，要面对。"],["九四","有命无咎，畴离祉。","时机开始转了，和伙伴一起受益。"],["九五","休否，大人吉；其亡其亡，系于苞桑。","困局快结束，仍要谨慎稳固。"],["上九","倾否，先否后喜。","闭塞要被打破了，先难后喜。"]]},{"no":13,"full":"天火同人","name":"同人","kw":"同心","ci":"同人：同人于野，亨。利涉大川，利君子贞。","ciB":"敞开心和人同行，能过大河。","xiang":"天与火，同人；君子以类族辨物。","xiangB":"合群的同时，也分清彼此。","up":"乾","lo":"离","yao":[["初九","同人于门，无咎。","出门就和人和睦，没有错。"],["六二","同人于宗，吝。","只和小圈子亲近，格局小了。"],["九三","伏戎于莽，升其高陵，三岁不兴。","暗中较劲没有用，放下吧。"],["九四","乘其墉，弗克攻，吉。","想争又停住了，这是好事。"],["九五","同人，先号啕而后笑，大师克相遇。","先哭后笑，终会和对的人相遇。"],["上九","同人于郊，无悔。","关系淡一点，也没有遗憾。"]]},{"no":14,"full":"火天大有","name":"大有","kw":"丰盛","ci":"大有：元亨。","ciB":"收获丰盛，诸事顺利。","xiang":"火在天上，大有。君子以遏恶扬善，顺天休命。","xiangB":"日子丰盛时，多做好事。","up":"离","lo":"乾","yao":[["初九","无交害，匪咎；艰则无咎。","不惹麻烦，记得艰难就不会错。"],["九二","大车以载，有攸往，无咎。","像大车一样能装，放心前行。"],["九三","公用，亨于天子，小人弗克。","有成果要分享，不独占。"],["九四","匪其彭，无咎。","不炫耀富足，就没有错。"],["六五","厥孚交如，威如，吉。","真诚又有分寸，人心归服。"],["上九","自天祐之，吉无不利。","像有天助，诸事都顺。"]]},{"no":15,"full":"地山谦","name":"谦","kw":"谦和","ci":"谦：亨，君子有终。","ciB":"谦和的人，事情会有好结果。","xiang":"地中有山，谦。君子以裒多益寡，称物平施。","xiangB":"多的拿一点补给少的，公平待人。","up":"坤","lo":"艮","yao":[["初六","谦谦君子，用涉大川，吉。","非常谦和，难关也能过去。"],["六二","鸣谦，贞吉。","谦和的名声传开，守正就好。"],["九三","劳谦，君子有终，吉。","有功劳仍谦和，会有好结局。"],["六四","无不利，㧑谦。","处处谦让，没有不顺的。"],["六五","不富以其邻，利用侵伐，无不利。","谦和中也要有原则，该出手就出手。"],["上六","鸣谦，利用行师，征邑国。","谦而有声望，可以整顿身边的事。"]]},{"no":16,"full":"雷地豫","name":"豫","kw":"愉悦","ci":"豫：利建侯行师。","ciB":"心情愉悦，正适合开始做事。","xiang":"雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。","xiangB":"用音乐和欢喜滋养自己。","up":"震","lo":"坤","yao":[["初六","鸣豫，凶。","得意忘形四处张扬，不好。"],["六二","介于石，不终日，贞吉。","像石头一样定，看准了就走。"],["六三","盱豫，悔。迟有悔。","看人脸色讨欢心，会后悔。"],["九四","由豫，大有得，勿疑，朋盍簪。","快乐由你而起，朋友聚过来。"],["六五","贞疾，恒不死。","长期的小困扰，不会压垮你。"],["上六","冥豫，成有渝，无咎。","沉溺享乐了，及时改就没事。"]]},{"no":17,"full":"泽雷随","name":"随","kw":"随顺","ci":"随：元亨，利贞，无咎。","ciB":"顺势而为，守正就没有错。","xiang":"泽中有雷，随。君子以向晦入宴息。","xiangB":"天黑了就休息，顺着节律走。","up":"兑","lo":"震","yao":[["初九","官有渝，贞吉。出门交有功。","情况变了，出门交往会有收获。"],["六二","系小子，失丈夫。","抓住小的，会丢了大的。"],["六三","系丈夫，失小子。随有求，得，利居贞。","选择重要的，舍掉次要的。"],["九四","随有获，贞凶。有孚，在道以明，何咎？","有收获也要坦诚，免得招疑。"],["九五","孚于嘉，吉。","真诚追随美好的事，吉。"],["上六","拘系之，乃从维之；王用亨于西山。","牢牢的羁绊，是真诚换来的。"]]},{"no":18,"full":"山风蛊","name":"蛊","kw":"整顿","ci":"蛊：元亨，利涉大川。先甲三日，后甲三日。","ciB":"积弊要清理，事前想清，事后跟进。","xiang":"山下有风，蛊。君子以振民育德。","xiangB":"提振士气，也培养自己。","up":"艮","lo":"巽","yao":[["初六","干父之蛊，有子，考无咎。厉，终吉。","修补前人留下的问题，终会好。"],["九二","干母之蛊，不可贞。","处理家里的事，要温和不要硬。"],["九三","干父之蛊，小有悔，无大咎。","改的过程有小遗憾，没有大错。"],["六四","裕父之蛊，往见吝。","对问题太宽容，拖下去会吃亏。"],["六五","干父之蛊，用誉。","把旧事修好，会得到称赞。"],["上九","不事王侯，高尚其事。","不追名逐利，做自己认为高尚的事。"]]},{"no":19,"full":"地泽临","name":"临","kw":"临近","ci":"临：元亨利贞。至于八月有凶。","ciB":"好时机来了，也要想到以后的变化。","xiang":"泽上有地，临。君子以教思无穷，容保民无疆。","xiangB":"用无尽的耐心去照顾人。","up":"坤","lo":"兑","yao":[["初九","咸临，贞吉。","以真心感动人，守正吉。"],["九二","咸临，吉，无不利。","用真心去感召，处处顺利。"],["六三","甘临，无攸利。既忧之，无咎。","光说好听话没用，意识到就改。"],["六四","至临，无咎。","亲自到场去面对，没有错。"],["六五","知临，大君之宜，吉。","用智慧去带人，很合适。"],["上六","敦临，吉，无咎。","厚道地对待，吉。"]]},{"no":20,"full":"风地观","name":"观","kw":"观察","ci":"观：盥而不荐，有孚颙若。","ciB":"像祭祀前洗手那样，心怀敬意地看。","xiang":"风行地上，观。先王以省方观民设教。","xiangB":"多走走看看，了解了再做。","up":"巽","lo":"坤","yao":[["初六","童观，小人无咎，君子吝。","只看表面，对你来说不够。"],["六二","窥观，利女贞。","从门缝里看，视野有限。"],["六三","观我生，进退。","看看自己的状态，再决定进退。"],["六四","观国之光，利用宾于王。","去看更大的世界，会被赏识。"],["九五","观我生，君子无咎。","反观自己的言行，就不会错。"],["上九","观其生，君子无咎。","被人看着时，也要守住自己。"]]},{"no":21,"full":"火雷噬嗑","name":"噬嗑","kw":"咬合","ci":"噬嗑：亨。利用狱。","ciB":"把卡住的东西咬碎，就通了。","xiang":"雷电噬嗑。先王以明罚敕法。","xiangB":"规则讲清楚，赏罚分明。","up":"离","lo":"震","yao":[["初九","屦校灭趾，无咎。","小错及时受罚，反而没事。"],["六二","噬肤灭鼻，无咎。","处理得重了点，问题不大。"],["六三","噬腊肉，遇毒。小吝，无咎。","碰到难啃的事，小有不快。"],["九四","噬干胏，得金矢。利艰贞，吉。","硬骨头里有收获，坚持就好。"],["六五","噬干肉，得黄金。贞厉，无咎。","难事中有所得，保持谨慎。"],["上九","何校灭耳，凶。","听不进劝告，后果会很重。"]]},{"no":22,"full":"山火贲","name":"贲","kw":"修饰","ci":"贲：亨。小利有攸往。","ciB":"适度打扮一下，小事会顺。","xiang":"山下有火，贲。君子以明庶政，无敢折狱。","xiangB":"日常的事理清楚，大事别轻断。","up":"艮","lo":"离","yao":[["初九","贲其趾，舍车而徒。","好好走路，不必坐华丽的车。"],["六二","贲其须。","装饰要依附于本身的好。"],["九三","贲如，濡如，永贞吉。","润泽又好看，长久守正就吉。"],["六四","贲如，皤如，白马翰如，匪寇婚媾。","素一点也很美，来的是好人。"],["六五","贲于丘园，束帛戋戋。吝，终吉。","简朴一点没关系，最后是好的。"],["上九","白贲，无咎。","最好的装饰是素净本色。"]]},{"no":23,"full":"山地剥","name":"剥","kw":"剥落","ci":"剥：不利有攸往。","ciB":"正在剥落的时候，先不要往前冲。","xiang":"山附于地，剥。上以厚下安宅。","xiangB":"把根基培厚，家才安稳。","up":"艮","lo":"坤","yao":[["初六","剥床以足，蔑贞，凶。","根基开始松动，要留心。"],["六二","剥床以辨，蔑贞，凶。","问题往上蔓延了，别忽视。"],["六三","剥之，无咎。","离开坏的环境，没有错。"],["六四","剥床以肤，凶。","已经伤到切身处，要停下来。"],["六五","贯鱼，以宫人宠，无不利。","有秩序地安排，反而顺利。"],["上九","硕果不食，君子得舆，小人剥庐。","留住最后的果实，它会重新发芽。"]]},{"no":24,"full":"地雷复","name":"复","kw":"回归","ci":"复：亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。","ciB":"转机来了，慢慢回到正轨。","xiang":"雷在地中，复。先王以至日闭关，商旅不行，后不省方。","xiangB":"新的开始很微弱，先静养。","up":"坤","lo":"震","yao":[["初九","不远复，无祇悔，元吉。","走偏不远就回来，很好。"],["六二","休复，吉。","安心地回头，吉。"],["六三","频复，厉，无咎。","反复犯又反复改，也算不错。"],["六四","中行独复。","在人群中独自回到正路。"],["六五","敦复，无悔。","踏实地回归，不后悔。"],["上六","迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征。","迷了路还不回头，会耽误很久。"]]},{"no":25,"full":"天雷无妄","name":"无妄","kw":"真诚","ci":"无妄：元亨利贞。其匪正有眚，不利有攸往。","ciB":"真诚不妄为，就会顺。","xiang":"天下雷行，物与无妄。先王以茂对时，育万物。","xiangB":"顺着时节，好好养育身边的事物。","up":"乾","lo":"震","yao":[["初九","无妄，往吉。","不带私心去做，吉。"],["六二","不耕获，不菑畲，则利有攸往。","做事别只盯着收获。"],["六三","无妄之灾。或系之牛，行人之得，邑人之灾。","有些麻烦不是你的错，别自责。"],["九四","可贞，无咎。","守住本分就好。"],["九五","无妄之疾，勿药有喜。","莫名的小毛病，不必乱治。"],["上九","无妄，行有眚，无攸利。","此时不宜行动，静一静。"]]},{"no":26,"full":"山天大畜","name":"大畜","kw":"积蓄","ci":"大畜：利贞，不家食，吉。利涉大川。","ciB":"积累够了，可以出去闯一闯。","xiang":"天在山中，大畜。君子以多识前言往行，以畜其德。","xiangB":"多读多学，积蓄自己。","up":"艮","lo":"乾","yao":[["初九","有厉，利已。","有危险，先停下。"],["九二","舆说輹。","车轴卸下，暂时不走。"],["九三","良马逐，利艰贞。曰闲舆卫，利有攸往。","好马可以跑了，仍要练习。"],["六四","童牛之牿，元吉。","问题在小时就约束好，大吉。"],["六五","豮豕之牙，吉。","从根源处化解冲突，吉。"],["上九","何天之衢，亨。","大路畅通，放手去走。"]]},{"no":27,"full":"山雷颐","name":"颐","kw":"颐养","ci":"颐：贞吉。观颐，自求口实。","ciB":"看看你吃什么、说什么，自己养自己。","xiang":"山下有雷，颐。君子以慎言语，节饮食。","xiangB":"说话谨慎，吃饭有节。","up":"艮","lo":"震","yao":[["初九","舍尔灵龟，观我朵颐，凶。","放下自己的好去羡慕别人，不好。"],["六二","颠颐，拂经；于丘颐，征凶。","依赖不该依赖的人，会出问题。"],["六三","拂颐，贞凶。十年勿用，无攸利。","违背养生之道，长期不利。"],["六四","颠颐，吉。虎视眈眈，其欲逐逐，无咎。","向下求助也可以，目标要专注。"],["六五","拂经，居贞吉。不可涉大川。","不按常理时，先安守，别冒险。"],["上九","由颐，厉吉。利涉大川。","你在照顾大家，辛苦但会好。"]]},{"no":28,"full":"泽风大过","name":"大过","kw":"承重","ci":"大过：栋桡。利有攸往，亨。","ciB":"担子太重，房梁都弯了，要做调整。","xiang":"泽灭木，大过。君子以独立不惧，遁世无闷。","xiangB":"独自站立也不怕，不被理解也不闷。","up":"兑","lo":"巽","yao":[["初六","藉用白茅，无咎。","多垫一层，小心谨慎就好。"],["九二","枯杨生稊，老夫得其女妻，无不利。","枯树发新芽，生机重来。"],["九三","栋桡，凶。","硬撑会塌，要求助。"],["九四","栋隆，吉。有它吝。","撑住了，但别分心。"],["九五","枯杨生花，老妇得其士夫，无咎无誉。","枯树开花，好看但不长久。"],["上六","过涉灭顶，凶，无咎。","冒险过深会危险，但心意无错。"]]},{"no":29,"full":"坎为水","name":"坎","kw":"涉险","ci":"坎：习坎。有孚，维心亨，行有尚。","ciB":"重重难关中，心里有信就通。","xiang":"水洊至，习坎。君子以常德行，习教事。","xiangB":"像水一样反复练习，日日不断。","up":"坎","lo":"坎","yao":[["初六","习坎，入于坎窞。凶。","掉进坑里，别再往深处去。"],["九二","坎有险，求小得。","危险中先求小小的收获。"],["六三","来之坎坎，险且枕，入于坎窞，勿用。","进退都难，先别动。"],["六四","樽酒簋贰，用缶，纳约自牖，终无咎。","简单真诚的心意，就能打通。"],["九五","坎不盈，祗既平，无咎。","水还没满，快要平了。"],["上六","系用徽纆，寘于丛棘，三岁不得，凶。","被困很久，要耐心等出路。"]]},{"no":30,"full":"离为火","name":"离","kw":"依附","ci":"离：利贞，亨。畜牝牛，吉。","ciB":"像火依附木头，温顺才能长明。","xiang":"明两作，离。大人以继明照四方。","xiangB":"让温暖和光亮持续下去。","up":"离","lo":"离","yao":[["初九","履错然，敬之，无咎。","脚步有点乱，恭敬就没错。"],["六二","黄离，元吉。","温暖的黄光，大吉。"],["九三","日昃之离。不鼓缶而歌，则大耋之嗟，凶。","太阳西斜，接受变化，别哀叹。"],["九四","突如其来如，焚如，死如，弃如。","来得太猛，会烧得太快。"],["六五","出涕沱若，戚嗟若，吉。","哭一哭、叹一叹，之后会好。"],["上九","王用出征，有嘉。折首，获匪其丑，无咎。","只处理关键的，不扩大。"]]},{"no":31,"full":"泽山咸","name":"咸","kw":"感应","ci":"咸：亨，利贞。取女吉。","ciB":"彼此心动，有好的感应。","xiang":"山上有泽，咸。君子以虚受人。","xiangB":"把心放空，才能接纳人。","up":"兑","lo":"艮","yao":[["初六","咸其拇。","刚有一点感觉，还在脚趾。"],["六二","咸其腓，凶，居吉。","急着动不好，先安静。"],["九三","咸其股，执其随，往吝。","盲目跟着走，会吃亏。"],["九四","贞吉悔亡，憧憧往来，朋从尔思。","心思反复，朋友会懂你。"],["九五","咸其脢，无悔。","平平淡淡的感应，也无悔。"],["上六","咸其辅、颊、舌。","只是嘴上说说，没走心。"]]},{"no":32,"full":"雷风恒","name":"恒","kw":"恒久","ci":"恒：亨，无咎，利贞。利有攸往。","ciB":"持之以恒，就会顺。","xiang":"雷风恒。君子以立不易方。","xiangB":"站定方向，不轻易改变。","up":"震","lo":"巽","yao":[["初六","浚恒，贞凶，无攸利。","一开始就要求太深，不好。"],["九二","悔亡。","坚持下去，遗憾会消失。"],["九三","不恒其德，或承之羞，贞吝。","三心二意，会让自己难堪。"],["九四","田无禽。","在没有猎物的地方守，白费力。"],["六五","恒其德，贞。妇人吉，夫子凶。","坚持要看场合，别太死板。"],["上六","振恒，凶。","总是动来动去，难以长久。"]]},{"no":33,"full":"天山遁","name":"遁","kw":"退隐","ci":"遁：亨。小利贞。","ciB":"适时退一步，反而通。","xiang":"天下有山，遁。君子以远小人，不恶而严。","xiangB":"远离消耗你的人，不必交恶。","up":"乾","lo":"艮","yao":[["初六","遁尾，厉。勿用有攸往。","退得太晚有危险，先别动。"],["六二","执之用黄牛之革，莫之胜说。","该坚持的，牢牢守住。"],["九三","系遁，有疾厉。畜臣妾，吉。","有牵挂难退，先照顾身边人。"],["九四","好遁，君子吉，小人否。","体面地离开，是好事。"],["九五","嘉遁，贞吉。","恰到好处地退，吉。"],["上九","肥遁，无不利。","从容地远离，一切都好。"]]},{"no":34,"full":"雷天大壮","name":"大壮","kw":"盛壮","ci":"大壮：利贞。","ciB":"力量强盛时，更要守正。","xiang":"雷在天上，大壮。君子以非礼弗履。","xiangB":"有力量也不越界。","up":"震","lo":"乾","yao":[["初九","壮于趾，征凶，有孚。","脚步太猛，往前会受伤。"],["九二","贞吉。","守正就好。"],["九三","小人用壮，君子用罔；贞厉，羝羊触藩，羸其角。","硬冲会被卡住，用巧劲。"],["九四","贞吉，悔亡；藩决不羸，壮于大舆之輹。","阻碍打开了，稳稳前进。"],["六五","丧羊于易，无悔。","放下好胜心，不后悔。"],["上六","羝羊触藩，不能退，不能遂，无攸利。艰则吉。","进退两难时，熬过就好。"]]},{"no":35,"full":"火地晋","name":"晋","kw":"上进","ci":"晋：康侯用锡马蕃庶，昼日三接。","ciB":"得到赏识，进展顺利。","xiang":"明出地上，晋。君子以自昭明德。","xiangB":"让自己的好被看见。","up":"离","lo":"坤","yao":[["初六","晋如，摧如，贞吉。罔孚，裕，无咎。","刚起步受挫，从容就好。"],["六二","晋如，愁如，贞吉。受兹介福，于其王母。","前进中有忧愁，会得到长辈照顾。"],["六三","众允，悔亡。","大家都认可你，遗憾消失。"],["九四","晋如鼫鼠，贞厉。","别像老鼠那样贪心不安。"],["六五","悔亡，失得勿恤，往吉，无不利。","得失不必挂心，往前走。"],["上九","晋其角，维用伐邑，厉吉无咎，贞吝。","冲到顶了，只处理身边事。"]]},{"no":36,"full":"地火明夷","name":"明夷","kw":"韬晦","ci":"明夷：利艰贞。","ciB":"光被遮住时，在艰难中守住自己。","xiang":"明入地中，明夷。君子以莅众用晦而明。","xiangB":"把光藏起来，心里依然明亮。","up":"坤","lo":"离","yao":[["初九","明夷于飞，垂其翼。君子于行，三日不食。有攸往，主人有言。","收起翅膀低飞，暂时避开。"],["六二","明夷，夷于左股，用拯马壮，吉。","受了点伤，有力的帮助会来。"],["九三","明夷于南狩，得其大首，不可疾，贞。","抓到关键了，但别急。"],["六四","入于左腹，获明夷之心，于出门庭。","看清了真相，就离开吧。"],["六五","箕子之明夷，利贞。","藏锋守正，等待天明。"],["上六","不明，晦。初登于天，后入于地。","盛极而衰，黑暗会过去。"]]},{"no":37,"full":"风火家人","name":"家人","kw":"家","ci":"家人：利女贞。","ciB":"家里各安其位，就和睦。","xiang":"风自火出，家人。君子以言有物而行有恒。","xiangB":"说话实在，做事有恒。","up":"巽","lo":"离","yao":[["初九","闲有家，悔亡。","一开始就立好家规，少烦恼。"],["六二","无攸遂，在中馈，贞吉。","把一日三餐照顾好，就是吉。"],["九三","家人嗃嗃，悔厉，吉；妇子嘻嘻，终吝。","严一点比太松好。"],["六四","富家，大吉。","让家富足起来，大吉。"],["九五","王假有家，勿恤，吉。","用爱感化家人，不必担心。"],["上九","有孚威如，终吉。","真诚又有威信，最后很好。"]]},{"no":38,"full":"火泽睽","name":"睽","kw":"相异","ci":"睽：小事吉。","ciB":"意见不合时，小事还可以做。","xiang":"上火下泽，睽。君子以同而异。","xiangB":"求大同，存小异。","up":"离","lo":"兑","yao":[["初九","悔亡，丧马勿逐，自复。见恶人，无咎。","走失的不必追，自会回来。"],["九二","遇主于巷，无咎。","在小巷里遇到对的人，没有错。"],["六三","见舆曳，其牛掣。其人天且劓，无初有终。","开头不顺，结局还好。"],["九四","睽孤，遇元夫。交孚，厉无咎。","孤单时遇到知己，彼此信任。"],["六五","悔亡，厥宗噬肤，往何咎？","亲近的人在帮你，放心去。"],["上九","睽孤，见豕负涂，载鬼一车。先张之弧，后说之弧，匪寇婚媾。往遇雨则吉。","疑心生暗鬼，误会解开就好。"]]},{"no":39,"full":"水山蹇","name":"蹇","kw":"难行","ci":"蹇：利西南，不利东北。利见大人，贞吉。","ciB":"路难走，换个方向，找人帮忙。","xiang":"山上有水，蹇。君子以反身修德。","xiangB":"遇到难处，先反观自己。","up":"坎","lo":"艮","yao":[["初六","往蹇来誉。","往前难，退回来反而好。"],["六二","王臣蹇蹇，匪躬之故。","为别人奔波辛苦，不是你的错。"],["九三","往蹇来反。","前路不通，回到身边人那里。"],["六四","往蹇来连。","往前难，回来和人联手。"],["九五","大蹇，朋来。","最难的时候，朋友会来。"],["上六","往蹇来硕，吉。利见大人。","回来会有大收获。"]]},{"no":40,"full":"雷水解","name":"解","kw":"解开","ci":"解：利西南。无所往，其来复吉。有攸往，夙吉。","ciB":"难题解开了，早点行动。","xiang":"雷雨作，解。君子以赦过宥罪。","xiangB":"原谅别人，也放过自己。","up":"震","lo":"坎","yao":[["初六","无咎。","松一口气，没有问题。"],["九二","田获三狐，得黄矢，贞吉。","清掉隐患，有所收获。"],["六三","负且乘，致寇至，贞吝。","背着东西又坐车，太招摇。"],["九四","解而拇，朋至斯孚。","放开不好的牵绊，真朋友会来。"],["六五","君子维有解，吉，有孚于小人。","你能解开心结，大家都信服。"],["上六","公用射隼于高墉之上，获之无不利。","时机到了，一举解决。"]]},{"no":41,"full":"山泽损","name":"损","kw":"减损","ci":"损：有孚，元吉，无咎，可贞。利有攸往。曷之用？二簋可用享。","ciB":"简单一点也足够，心诚就好。","xiang":"山下有泽，损。君子以惩忿窒欲。","xiangB":"少发脾气，少一点欲望。","up":"艮","lo":"兑","yao":[["初九","已事遄往，无咎，酌损之。","帮完忙就走，适度付出。"],["九二","利贞，征凶。弗损，益之。","不必牺牲自己，也能帮到人。"],["六三","三人行则损一人；一人行则得其友。","人多时减一个，独行反得知己。"],["六四","损其疾，使遄有喜，无咎。","改掉毛病，喜事很快来。"],["六五","或益之十朋之龟，弗克违。元吉。","有人主动帮你，大吉。"],["上九","弗损，益之，无咎。贞吉。利有攸往，得臣无家。","不损别人而让人得益，人心归附。"]]},{"no":42,"full":"风雷益","name":"益","kw":"增益","ci":"益：利有攸往，利涉大川。","ciB":"得到帮助的时候，适合前进。","xiang":"风雷，益。君子以见善则迁，有过则改。","xiangB":"见好就学，有错就改。","up":"巽","lo":"震","yao":[["初九","利用为大作，元吉，无咎。","适合做一件大事。"],["六二","或益之十朋之龟，弗克违，永贞吉。王用享于帝，吉。","好处来了，长期守正。"],["六三","益之用凶事，无咎。有孚中行，告公用圭。","在难事中得到帮助，真诚面对。"],["六四","中行，告公从。利用为依迁国。","走正道，提议会被采纳。"],["九五","有孚惠心，勿问元吉。有孚惠我德。","真心待人，不必问就是吉。"],["上九","莫益之，或击之，立心勿恒，凶。","只想得好处，会被反击。"]]},{"no":43,"full":"泽天夬","name":"夬","kw":"决断","ci":"夬：扬于王庭，孚号有厉。告自邑，不利即戎，利有攸往。","ciB":"该做决定了，但别用硬拼的方式。","xiang":"泽上于天，夬。君子以施禄及下，居德则忌。","xiangB":"把福分分给别人，别囤着。","up":"兑","lo":"乾","yao":[["初九","壮于前趾，往不胜为咎。","冲得太快，会失败。"],["九二","惕号，莫夜有戎，勿恤。","保持警觉，就不怕突发。"],["九三","壮于頄，有凶。君子夬夬独行，遇雨若濡，有愠，无咎。","喜怒别写在脸上，独行无妨。"],["九四","臀无肤，其行次且。牵羊悔亡，闻言不信。","坐立不安，好建议也听不进。"],["九五","苋陆夬夬，中行无咎。","该断就断，走中道。"],["上六","无号，终有凶。","最后再哭也晚了，及早决断。"]]},{"no":44,"full":"天风姤","name":"姤","kw":"相遇","ci":"姤：女壮，勿用取女。","ciB":"突然的相遇，别太快投入。","xiang":"天下有风，姤。后以施命诰四方。","xiangB":"把想法说清楚，传出去。","up":"乾","lo":"巽","yao":[["初六","系于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅。","先刹住车，守正吉。"],["九二","包有鱼，无咎，不利宾。","自己的事自己管好。"],["九三","臀无肤，其行次且。厉，无大咎。","进退不安，没有大碍。"],["九四","包无鱼，起凶。","失去了人心，别急着行动。"],["九五","以杞包瓜，含章，有陨自天。","包容又内敛，好事会从天而降。"],["上九","姤其角，吝，无咎。","太孤高难相遇，也无大错。"]]},{"no":45,"full":"泽地萃","name":"萃","kw":"聚集","ci":"萃：亨，王假有庙。利见大人，亨，利贞。用大牲吉。利有攸往。","ciB":"大家聚在一起，有好的事。","xiang":"泽上于地，萃。君子以除戎器，戒不虞。","xiangB":"人多时，做好准备防意外。","up":"兑","lo":"坤","yao":[["初六","有孚不终，乃乱乃萃。若号，一握为笑。勿恤，往无咎。","一开始乱，后来会聚拢。"],["六二","引吉，无咎。孚乃利用禴。","被人引荐，心意真就够。"],["六三","萃如，嗟如，无攸利。往无咎，小吝。","想加入却叹气，主动去就好。"],["九四","大吉，无咎。","聚人得当，大吉无咎。"],["九五","萃有位，无咎。匪孚，元永贞，悔亡。","身在其位，用长久的真诚聚人。"],["上六","赍咨涕洟，无咎。","哭一场也没关系。"]]},{"no":46,"full":"地风升","name":"升","kw":"上升","ci":"升：元亨。用见大人，勿恤，南征吉。","ciB":"慢慢往上长，不必担心。","xiang":"地中生木，升。君子以顺德，积小以高大。","xiangB":"积小成大，顺着本性长。","up":"坤","lo":"巽","yao":[["初六","允升，大吉。","被认可地上升，大吉。"],["九二","孚乃利用禴，无咎。","心诚就好，不必铺张。"],["九三","升虚邑。","前路畅通，像走进空城。"],["六四","王用亨于岐山，吉，无咎。","顺着正道上升，吉。"],["六五","贞吉，升阶。","一级一级地上台阶。"],["上六","冥升，利于不息之贞。","盲目往上时，要守住初心。"]]},{"no":47,"full":"泽水困","name":"困","kw":"受困","ci":"困：亨，贞，大人吉，无咎。有言不信。","ciB":"被困时守住自己就会通，少辩解。","xiang":"泽无水，困。君子以致命遂志。","xiangB":"处境再难，也不放弃心愿。","up":"兑","lo":"坎","yao":[["初六","臀困于株木，入于幽谷，三岁不觌。","困在低处，要很久才走出。"],["九二","困于酒食，朱绂方来，利用享祀。征凶，无咎。","不缺吃穿却心累，机会快来了。"],["六三","困于石，据于蒺藜。入于其宫，不见其妻，凶。","别去碰不该碰的硬石头。"],["九四","来徐徐，困于金车，吝，有终。","来得慢一点，最后会好。"],["九五","劓刖，困于赤绂。乃徐，有说，利用祭祀。","被上下夹着难受，会慢慢缓解。"],["上六","困于葛藟，于臲卼，曰动悔。有悔，征吉。","被藤蔓缠着，动起来就能脱身。"]]},{"no":48,"full":"水风井","name":"井","kw":"滋养","ci":"井：改邑不改井，无丧无得。往来井井。汔至亦未繘井，羸其瓶，凶。","ciB":"像井一样稳定地滋养人，坚持到底。","xiang":"木上有水，井。君子以劳民劝相。","xiangB":"大家互相勉励，一起努力。","up":"坎","lo":"巽","yao":[["初六","井泥不食，旧井无禽。","旧井淤了，该清理了。"],["九二","井谷射鲋，瓮敝漏。","有水却漏了，没有发挥出来。"],["九三","井渫不食，为我心恻。可用汲，王明，并受其福。","井水清了没人喝，别灰心。"],["六四","井甃，无咎。","修补井壁，打好基础。"],["九五","井冽寒泉，食。","井水清冽，可以分享了。"],["上六","井收勿幕，有孚元吉。","井口敞开，大家都能取用，大吉。"]]},{"no":49,"full":"泽火革","name":"革","kw":"变革","ci":"革：己日乃孚。元亨利贞。悔亡。","ciB":"时机成熟才改变，大家会信服。","xiang":"泽中有火，革。君子以治历明时。","xiangB":"看清时节，顺时而变。","up":"兑","lo":"离","yao":[["初九","巩用黄牛之革。","还不到时候，先稳住。"],["六二","己日乃革之。征吉，无咎。","时候到了，可以改了。"],["九三","征凶贞厉。革言三就，有孚。","改变要反复商量，不可急。"],["九四","悔亡，有孚，改命，吉。","带着诚意去改，吉。"],["九五","大人虎变，未占有孚。","大刀阔斧地改，大家信你。"],["上六","君子豹变，小人革面。征凶，居贞吉。","改变后好好安顿，别再折腾。"]]},{"no":50,"full":"火风鼎","name":"鼎","kw":"立新","ci":"鼎：元吉，亨。","ciB":"器已立成，正是把好东西端出来的时候。","xiang":"木上有火，鼎。君子以正位凝命。","xiangB":"站稳自己的位置，把要紧的事做实。","up":"离","lo":"巽","yao":[["初六","鼎颠趾，利出否。得妾以其子，无咎。","先把旧渣倒干净，才装得下新的。"],["九二","鼎有实，我仇有疾，不我能即，吉。","你手里有真东西，旁人近不了身。"],["九三","鼎耳革，其行塞，雉膏不食。方雨，亏悔，终吉。","一时用不上不要紧，雨来了自然顺。"],["九四","鼎折足，覆公餗，其形渥，凶。","别接超出自己分量的担子。"],["六五","鼎黄耳金铉，利贞。","把手配得正好，稳稳守住就好。"],["上九","鼎玉铉，大吉，无不利。","温润又坚定，做什么都顺。"]]},{"no":51,"full":"震为雷","name":"震","kw":"震动","ci":"震：亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。","ciB":"突如其来的惊吓，稳住就能笑着过去。","xiang":"洊雷，震。君子以恐惧修省。","xiangB":"受了惊，正好反省自己。","up":"震","lo":"震","yao":[["初九","震来虩虩，后笑言哑哑，吉。","先吓一跳，后来笑出来。"],["六二","震来厉，亿丧贝。跻于九陵，勿逐，七日得。","有损失不用追，过几天会回来。"],["六三","震苏苏，震行无眚。","有点慌，但动起来就没事。"],["九四","震遂泥。","被惊得陷住了，缓一缓。"],["六五","震往来厉，亿无丧，有事。","反复受惊，但不会失去什么。"],["上六","震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。","被吓到发抖时，先别行动。"]]},{"no":52,"full":"艮为山","name":"艮","kw":"止","ci":"艮：艮其背，不获其身。行其庭，不见其人。无咎。","ciB":"该停就停，心静下来就没事。","xiang":"兼山，艮。君子以思不出其位。","xiangB":"想的事不超出自己的位置。","up":"艮","lo":"艮","yao":[["初六","艮其趾，无咎。利永贞。","在起步时停下，没有错。"],["六二","艮其腓，不拯其随，其心不快。","想停却停不住，心里不舒服。"],["九三","艮其限，列其夤，厉薰心。","硬压着不动，会憋得难受。"],["六四","艮其身，无咎。","让身体安静下来，好。"],["六五","艮其辅，言有序，悔亡。","管住嘴，说话有条理。"],["上九","敦艮，吉。","踏实地停下来，吉。"]]},{"no":53,"full":"风山渐","name":"渐","kw":"渐进","ci":"渐：女归吉，利贞。","ciB":"一步一步来，水到渠成。","xiang":"山上有木，渐。君子以居贤德善俗。","xiangB":"像山上的树，慢慢长成。","up":"巽","lo":"艮","yao":[["初六","鸿渐于干，小子厉。有言，无咎。","刚起步有人说闲话，没关系。"],["六二","鸿渐于磐，饮食衎衎，吉。","落在稳固处，吃好喝好。"],["九三","鸿渐于陆，夫征不复，妇孕不育，凶。利御寇。","走得太远不回头，要小心。"],["六四","鸿渐于木，或得其桷，无咎。","找到一个能栖身的枝头。"],["九五","鸿渐于陵，妇三岁不孕，终莫之胜，吉。","等得久一点，终会如愿。"],["上九","鸿渐于陆，其羽可用为仪，吉。","飞得高远，成为别人的榜样。"]]},{"no":54,"full":"雷泽归妹","name":"归妹","kw":"归属","ci":"归妹：征凶，无攸利。","ciB":"身不由己的处境，先别急着往前。","xiang":"泽上有雷，归妹。君子以永终知敝。","xiangB":"想得长远，看清不足。","up":"震","lo":"兑","yao":[["初九","归妹以娣，跛能履，征吉。","位置不高也能前行。"],["九二","眇能视，利幽人之贞。","看不全也没关系，安静守着。"],["六三","归妹以须，反归以娣。","等待之后，回到合适的位置。"],["九四","归妹愆期，迟归有时。","迟一点没关系，时候会到。"],["六五","帝乙归妹，其君之袂不如其娣之袂良。月几望，吉。","朴素胜过华丽，吉。"],["上六","女承筐无实，士刲羊无血，无攸利。","只有形式没有内容，没什么用。"]]},{"no":55,"full":"雷火丰","name":"丰","kw":"盛大","ci":"丰：亨。王假之，勿忧，宜日中。","ciB":"正当丰盛，不必担忧，像正午的太阳。","xiang":"雷电皆至，丰。君子以折狱致刑。","xiangB":"看清事实再下判断。","up":"震","lo":"离","yao":[["初九","遇其配主，虽旬无咎；往有尚。","遇到相配的人，一起前进。"],["六二","丰其蔀，日中见斗。往得疑疾。有孚发若，吉。","被遮住光时，真诚会打开局面。"],["九三","丰其沛，日中见沬。折其右肱，无咎。","暂时受挫，不是你的错。"],["九四","丰其蔀，日中见斗。遇其夷主，吉。","遇到同频的人，吉。"],["六五","来章，有庆誉，吉。","引来人才，有喜有誉。"],["上六","丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶。","把自己关起来，会很孤单。"]]},{"no":56,"full":"火山旅","name":"旅","kw":"在途","ci":"旅：小亨，旅贞吉。","ciB":"在外漂泊，守住自己就好。","xiang":"山上有火，旅。君子以明慎用刑而不留狱。","xiangB":"处理事情明快，不拖延。","up":"离","lo":"艮","yao":[["初六","旅琐琐，斯其所取灾。","在外斤斤计较，会招麻烦。"],["六二","旅即次，怀其资，得童仆，贞。","有落脚处、有盘缠，还有人帮。"],["九三","旅焚其次，丧其童仆，贞厉。","太傲慢会失去依靠。"],["九四","旅于处，得其资斧，我心不快。","有收获，心里却不踏实。"],["六五","射雉，一矢亡，终以誉命。","小有付出，最终得到认可。"],["上九","鸟焚其巢，旅人先笑后号啕。丧牛于易，凶。","得意忘形会失去安身之处。"]]},{"no":57,"full":"巽为风","name":"巽","kw":"顺入","ci":"巽：小亨。利有攸往，利见大人。","ciB":"像风一样柔和地进入，会顺。","xiang":"随风，巽。君子以申命行事。","xiangB":"把话说清楚，再去做。","up":"巽","lo":"巽","yao":[["初六","进退，利武人之贞。","犹豫不决时，拿出果断来。"],["九二","巽在床下，用史巫纷若，吉，无咎。","太过谦卑时，坦诚说出来就好。"],["九三","频巽，吝。","一再退让，会吃亏。"],["六四","悔亡，田获三品。","后悔消失，收获丰富。"],["九五","贞吉，悔亡，无不利。无初有终。先庚三日，后庚三日，吉。","改变之前想清，之后跟进。"],["上九","巽在床下，丧其资斧，贞凶。","过分退让，会失去自己的力量。"]]},{"no":58,"full":"兑为泽","name":"兑","kw":"喜悦","ci":"兑：亨，利，贞。","ciB":"喜悦相处，守住分寸。","xiang":"丽泽，兑。君子以朋友讲习。","xiangB":"和朋友一起学习交流。","up":"兑","lo":"兑","yao":[["初九","和兑，吉。","平和的快乐，吉。"],["九二","孚兑，吉，悔亡。","真诚的快乐，没有遗憾。"],["六三","来兑，凶。","刻意讨好来的快乐，不好。"],["九四","商兑未宁，介疾有喜。","远离不好的，才有真喜。"],["九五","孚于剥，有厉。","别轻信会消耗你的人。"],["上六","引兑。","被引诱的快乐，要警惕。"]]},{"no":59,"full":"风水涣","name":"涣","kw":"化开","ci":"涣：亨，王假有庙。利涉大川，利贞。","ciB":"心结化开，可以重新出发。","xiang":"风行水上，涣。先王以享于帝，立庙。","xiangB":"找到让心安定的寄托。","up":"巽","lo":"坎","yao":[["初六","用拯马壮，吉。","及早求助，吉。"],["九二","涣奔其机，悔亡。","赶紧找到可以依靠的地方。"],["六三","涣其躬，无悔。","放下自我，不后悔。"],["六四","涣其群，元吉。涣有丘，匪夷所思。","离开小圈子，看到更大的。"],["九五","涣汗，其大号涣，王居，无咎。","像出汗一样发散出去，没问题。"],["上九","涣其血，去逖出，无咎。","远离伤害，没有错。"]]},{"no":60,"full":"水泽节","name":"节","kw":"节制","ci":"节：亨，苦节不可贞。","ciB":"有节制就顺，但别苦着自己。","xiang":"泽上有水，节。君子以制数度，议德行。","xiangB":"给生活定个合适的度。","up":"坎","lo":"兑","yao":[["初九","不出户庭，无咎。","这时待在家里，没有错。"],["九二","不出门庭，凶。","该出门时不出，会错过。"],["六三","不节若，则嗟若。无咎。","没节制会后悔，改了就好。"],["六四","安节，亨。","自在的节制，很顺。"],["九五","甘节，吉，往有尚。","甘心情愿的节制，吉。"],["上六","苦节，贞凶。悔亡。","太苦的克制，不能长久。"]]},{"no":61,"full":"风泽中孚","name":"中孚","kw":"诚信","ci":"中孚：豚鱼，吉。利涉大川，利贞。","ciB":"真诚能打动所有人。","xiang":"泽上有风，中孚。君子以议狱缓死。","xiangB":"多一点宽厚和体谅。","up":"巽","lo":"兑","yao":[["初九","虞吉，有它不燕。","心安定就好，别三心二意。"],["九二","鸣鹤在阴，其子和之。我有好爵，吾与尔靡之。","真心的呼唤，总有人回应。"],["六三","得敌，或鼓或罢，或泣或歌。","情绪起起落落，因外物而动。"],["六四","月几望，马匹亡，无咎。","放下一些牵绊，没有错。"],["九五","有孚挛如，无咎。","真诚把大家连在一起。"],["上九","翰音登于天，贞凶。","声音大过实际，不长久。"]]},{"no":62,"full":"雷山小过","name":"小过","kw":"小心","ci":"小过：亨，利贞。可小事，不可大事。飞鸟遗之音。不宜上，宜下，大吉。","ciB":"小事可做，大事缓缓，往低处走。","xiang":"山上有雷，小过。君子以行过乎恭，丧过乎哀，用过乎俭。","xiangB":"恭敬一点、节俭一点，不为过。","up":"震","lo":"艮","yao":[["初六","飞鸟以凶。","飞得太急，会出事。"],["六二","过其祖，遇其妣。不及其君，遇其臣，无咎。","没遇到想见的，遇到合适的也好。"],["九三","弗过防之，从或戕之，凶。","要防着点，别大意。"],["九四","无咎，弗过遇之，往厉必戒。勿用，永贞。","别主动出击，保持警觉。"],["六五","密云不雨，自我西郊。公弋取彼在穴。","云很厚还没下雨，自己先准备。"],["上六","弗遇过之，飞鸟离之，凶。是谓灾眚。","走过头了，要赶紧回来。"]]},{"no":63,"full":"水火既济","name":"既济","kw":"已成","ci":"既济：亨小，利贞。初吉，终乱。","ciB":"事情成了，守成比开始更难。","xiang":"水在火上，既济。君子以思患而豫防之。","xiangB":"成功时，想想可能的隐患。","up":"坎","lo":"离","yao":[["初九","曳其轮，濡其尾，无咎。","放慢一点，没有错。"],["六二","妇丧其茀，勿逐，七日得。","丢了东西别追，会回来。"],["九三","高宗伐鬼方，三年克之。小人勿用。","大事要很久，别用错人。"],["六四","繻有衣袽，终日戒。","随时准备好补漏洞。"],["九五","东邻杀牛，不如西邻之禴祭，实受其福。","心意比排场重要。"],["上六","濡其首，厉。","得意之时，别冒进到没顶。"]]},{"no":64,"full":"火水未济","name":"未济","kw":"未完","ci":"未济：亨。小狐汔济，濡其尾，无攸利。","ciB":"还没完成，最后一步要小心。","xiang":"火在水上，未济。君子以慎辨物居方。","xiangB":"分清楚每样东西该在的位置。","up":"离","lo":"坎","yao":[["初六","濡其尾，吝。","准备不足就出发，会狼狈。"],["九二","曳其轮，贞吉。","先稳住，不着急。"],["六三","未济，征凶，利涉大川。","条件不够别硬冲，可借力过河。"],["九四","贞吉，悔亡，震用伐鬼方。三年有赏于大国。","坚持下去，努力会被看见。"],["六五","贞吉，无悔，君子之光。有孚，吉。","你的光芒和真诚，会被看见。"],["上九","有孚于饮酒，无咎。濡其首，有孚失是。","可以放松庆祝，但别过头。"]]}];
const TRI=[{"k":"qian","name":"乾","nat":"天","num":1,"wx":"金","bits":"111","xq":"健","xqd":"刚健、主动、不停歇","tip":"拿出主心骨，自己做决定。","zr":"天空、晴天、冰","rw":"父亲、领导、长辈","st":"头","dx":"圆的东西、金饰玉器、手表、贵重物","dw":"马、狮子","fw":"西北 · 秋冬之交"},{"k":"dui","name":"兑","nat":"泽","num":2,"wx":"金","bits":"110","xq":"悦","xqd":"喜悦、说话、交流","tip":"说出来，笑一笑，和人聊一聊。","zr":"湖泊、池塘、雨后的积水","rw":"少女、爱聊天的朋友、唱歌的人","st":"嘴、舌头、喉咙","dx":"有缺口的杯碗、乐器、甜点、小金属","dw":"羊","fw":"西 · 秋"},{"k":"li","name":"离","nat":"火","num":3,"wx":"火","bits":"101","xq":"丽","xqd":"光明、依附、看见","tip":"看清楚，也让自己亮起来。","zr":"火、太阳、闪电、晴热天","rw":"中女、读书写字的人、美丽的人","st":"眼睛、心","dx":"灯、镜子、屏幕、证件文书、中空的东西","dw":"雉鸡、金鱼、螃蟹、乌龟","fw":"南 · 夏"},{"k":"zhen","name":"震","nat":"雷","num":4,"wx":"木","bits":"100","xq":"动","xqd":"行动、开始、响动","tip":"动起来，先迈出第一步。","zr":"雷、春雷、地动","rw":"长男、爱运动的人","st":"脚","dx":"车、鼓、手机铃声、新芽、竹子","dw":"龙、会跳的动物","fw":"东 · 春"},{"k":"xun","name":"巽","nat":"风","num":5,"wx":"木","bits":"011","xq":"入","xqd":"柔顺、渗透、传播","tip":"柔一点，慢慢渗进去。","zr":"风、香气","rw":"长女、商人、老师","st":"大腿、头发、呼吸","dx":"绳子、线、长条形的东西、植物、扇子","dw":"鸡","fw":"东南 · 春夏之交"},{"k":"kan","name":"坎","nat":"水","num":6,"wx":"水","bits":"010","xq":"陷","xqd":"险难、流动、智慧","tip":"有难处，也藏着智慧，别怕。","zr":"水、雨、月亮、夜晚、河流","rw":"中男、在外漂泊的人","st":"耳朵、血液、肾","dx":"酒和饮料、流动的东西、弯弯曲曲的东西","dw":"猪、鱼","fw":"北 · 冬"},{"k":"gen","name":"艮","nat":"山","num":7,"wx":"土","bits":"001","xq":"止","xqd":"停止、守住、界限","tip":"停一停，守住你的位置。","zr":"山、石头、小路","rw":"少男、守门的人","st":"手、鼻子、背","dx":"门、桌子、箱子、房子","dw":"狗、老鼠","fw":"东北 · 冬春之交"},{"k":"kun","name":"坤","nat":"地","num":8,"wx":"土","bits":"000","xq":"顺","xqd":"包容、承载、柔顺","tip":"包容一点，先承接下来。","zr":"大地、田野、平原","rw":"母亲、众人、年长的女性","st":"肚子、脾胃","dx":"布、锅、纸张、方形和柔软的东西","dw":"牛","fw":"西南 · 夏秋之交"}];
