function wxSVG(){
  const P={木:[160,52],火:[268,130],土:[226,256],金:[94,256],水:[52,130]},C={木:['#e3ecdf','#a8b896','#4b6b4a'],火:['#f6dfdc','#e0a294','#8f4a43'],土:['#f4ecd5','#dcc490','#8a6d35'],金:['#ece8e2','#c2b9ac','#6e665d'],水:['#e0e7ef','#8fa4ba','#4b5d73']};
  const ring=['木','火','土','金','水'],star=[['木','土'],['土','水'],['水','火'],['火','金'],['金','木']],R=34;
  const edge=(a,b,off)=>{const [x1,y1]=P[a],[x2,y2]=P[b],dx=x2-x1,dy=y2-y1,L=Math.hypot(dx,dy),ux=dx/L,uy=dy/L;return [x1+ux*(R+off),y1+uy*(R+off),x2-ux*(R+off+4),y2-uy*(R+off+4)]};
  let s='<svg viewBox="0 0 320 300"><defs><marker id="ag" markerWidth="8" markerHeight="8" refX="5" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#4f6a4a"/></marker><marker id="ar" markerWidth="8" markerHeight="8" refX="5" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#8f4a43"/></marker></defs>';
  ring.forEach((a,i)=>{const b=ring[(i+1)%5],[x1,y1,x2,y2]=edge(a,b,4),mx=(x1+x2)/2,my=(y1+y2)/2,cx=160,cy=160,ox=(mx-cx)*.22,oy=(my-cy)*.22;s+=`<path d="M${x1} ${y1} Q${mx+ox} ${my+oy} ${x2} ${y2}" fill="none" stroke="#4f6a4a" stroke-width="2.4" marker-end="url(#ag)"/>`});
  star.forEach(([a,b])=>{const [x1,y1,x2,y2]=edge(a,b,4);s+=`<path d="M${x1} ${y1} L${x2} ${y2}" stroke="#8f4a43" stroke-width="1.8" stroke-dasharray="5 5" marker-end="url(#ar)"/>`});
  ring.forEach(a=>{const [x,y]=P[a],c=C[a];s+=`<circle cx="${x}" cy="${y}" r="${R}" fill="${c[0]}" stroke="${c[1]}" stroke-width="3"/><text x="${x}" y="${y+12}" text-anchor="middle" font-size="32" fill="${c[2]}" style="font-family:var(--xw)">${a}</text>`});
  return s+'</svg>';
}

